#pragma once
// 块缓存：多个线程并发 get()/release()；条目被最后一个持有者释放时回收。
// 约定：调用方只用 release() 归还自己 get() 得到的条目；key 由上层保证非空。
#include <atomic>
#include <mutex>
#include <string>
#include <unordered_map>

struct Entry {
    std::string key;
    std::string data;
    std::atomic<int> refs{1};   // 缓存表本身持有 1 个引用
};

class BlockCache {
public:
    Entry* get(const std::string& key) {
        Entry* e;
        {
            std::lock_guard<std::mutex> g(mu_);
            auto it = map_.find(key);
            if (it == map_.end()) return nullptr;
            e = it->second;
        }
        e->refs.fetch_add(1, std::memory_order_relaxed);
        return e;
    }

    void release(Entry* e) {
        if (e->refs.load(std::memory_order_acquire) == 1) {
            delete e;
        } else {
            e->refs.fetch_sub(1, std::memory_order_release);
        }
    }

    // 淘汰：从表中摘除并放掉表持有的那个引用。
    void evict(const std::string& key) {
        Entry* e = nullptr;
        {
            std::lock_guard<std::mutex> g(mu_);
            auto it = map_.find(key);
            if (it == map_.end()) return;
            e = it->second;
            map_.erase(it);
        }
        release(e);
    }

    void put(const std::string& key, std::string data) {
        auto* e = new Entry{key, std::move(data)};
        std::lock_guard<std::mutex> g(mu_);
        map_[key] = e;   // key 由上层保证此前不存在
    }

private:
    std::mutex mu_;
    std::unordered_map<std::string, Entry*> map_;
};

