#pragma once
// 单写者、多读者的 seqlock：写者更新 Stats，读者无锁读取一致快照。
// 约定：只有统计线程调用 write()；Stats 是平凡可拷贝的 POD。
#include <atomic>
#include <cstdint>

struct Stats { uint64_t ops; uint64_t bytes; uint64_t errors; };

class StatsSeqlock {
public:
    void write(const Stats& s) {
        seq_.fetch_add(1, std::memory_order_relaxed);   // 变为奇数：写入中
        data_ = s;
        seq_.fetch_add(1, std::memory_order_relaxed);   // 变回偶数：写完
    }

    Stats read() const {
        for (;;) {
            uint64_t s1 = seq_.load(std::memory_order_relaxed);
            Stats copy = data_;
            uint64_t s2 = seq_.load(std::memory_order_relaxed);
            if (s1 == s2) return copy;
        }
    }

private:
    std::atomic<uint64_t> seq_{0};
    Stats data_{};
};
